def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    import heapq

    events = []
    for i, op in enumerate(ops):
        events.append((op[1], i, 1))
        events.append((op[2] + 1, i, -1))
    events.sort()

    active = [False] * len(ops)
    erases = []
    paints = []
    counts = {}

    pos = 0
    while pos < len(events):
        x = events[pos][0]

        while pos < len(events) and events[pos][0] == x:
            _, i, kind = events[pos]
            if kind == 1:
                active[i] = True
                if ops[i][0] == 0:
                    heapq.heappush(erases, -i)
                else:
                    heapq.heappush(paints, (-ops[i][3], -i))
            else:
                active[i] = False
            pos += 1

        while erases and not active[-erases[0]]:
            heapq.heappop(erases)

        last_erase = -erases[0] if erases else -1
        while paints and (
            not active[-paints[0][1]] or -paints[0][1] < last_erase
        ):
            heapq.heappop(paints)

        if paints and pos < len(events):
            colour = -paints[0][0]
            counts[colour] = counts.get(colour, 0) + events[pos][0] - x

    return [[colour, counts[colour]] for colour in sorted(counts)]
